                    : new BigDecimal(i.get("levyPct").toString());
            // Each line is rounded to the cent first and the rounded lines are added up. A discount takes a
            // percentage off the subtotal; sales tax and a levy each add their percentage of every taxable
            // line after its discount, rounded per line and then added up. The amount is the discounted
            // subtotal plus the tax plus the levy.
            // An invoice for a tax-exempt client carries no tax or levy on any line.
            long projectId = ((Number) i.get("projectId")).longValue();
            Map<String, Object> client = jdbc.queryForMap(
                    "SELECT c.tax_inclusive, c.tax_exempt FROM project p JOIN client c ON c.id = p.client_id WHERE p.id = ?",
                    projectId);
            boolean taxInclusive = Boolean.TRUE.equals(client.get("TAX_INCLUSIVE"));
            boolean taxExempt = Boolean.TRUE.equals(client.get("TAX_EXEMPT"));
            BigDecimal discountAmount = i.get("discountAmount") == null ? BigDecimal.ZERO
                    : new BigDecimal(i.get("discountAmount").toString());
            // A flat discount is taken off after the percentage (never more than is left) and is shared
            // across the lines in proportion to what each charges.
            // Each line is first taken down by its own discount, if it has one.
            List<BigDecimal> lines = lineItems.stream().map(l -> {
                BigDecimal gross = new BigDecimal(l.get("qty").toString())
                        .multiply(new BigDecimal(l.get("unitPrice").toString())).setScale(2, RoundingMode.HALF_UP);
                return gross.subtract(gross.multiply(lineDiscountPct(l)).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP));
            }).toList();
            BigDecimal subtotal = lines.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            BigDecimal pctDiscount = subtotal.multiply(discountPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
            BigDecimal flatDiscount = discountAmount.setScale(2, RoundingMode.HALF_UP)
                    .min(subtotal.subtract(pctDiscount).max(BigDecimal.ZERO.setScale(2)));
            BigDecimal tax = BigDecimal.ZERO.setScale(2);
            BigDecimal levy = BigDecimal.ZERO.setScale(2);
            for (int n = 0; n < lineItems.size(); n++) {
                BigDecimal line = lines.get(n);
                if (!taxExempt && !Boolean.TRUE.equals(lineItems.get(n).get("taxExempt"))) {
                    BigDecimal flatShare = subtotal.signum() == 0 ? BigDecimal.ZERO
                            : flatDiscount.multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
                    BigDecimal base = line.subtract(
                            line.multiply(discountPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP))
                            .subtract(flatShare);
                    tax = tax.add(base.multiply(taxPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP));
                    levy = levy.add(base.multiply(levyPct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP));
                }
            }
            BigDecimal discount = pctDiscount.add(flatDiscount);
            BigDecimal discounted = subtotal.subtract(discount);
            // An invoice for a tax-inclusive client already has the taxes inside its prices, so its amount is
            // just the discounted subtotal.
            // An early-payment discount offered is just recorded; it does not change the amount owed.
            BigDecimal earlyPaymentPct = i.get("earlyPaymentPct") == null ? BigDecimal.ZERO
                    : new BigDecimal(i.get("earlyPaymentPct").toString());
            // A flat surcharge (such as a handling fee) is added on last, after any tax.
            BigDecimal surcharge = i.get("surcharge") == null ? BigDecimal.ZERO
                    : new BigDecimal(i.get("surcharge").toString());
            int earlyPaymentDays = i.get("earlyPaymentDays") == null ? 0 : ((Number) i.get("earlyPaymentDays")).intValue();
            jdbc.update("INSERT INTO invoice (id, project_id, amount, discount_pct, discount_amount, tax_pct, levy_pct, surcharge, tax_inclusive, tax_exempt,"
                    + " early_payment_pct, early_payment_days, status, issued_date, due_date) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    invoiceId, projectId,
                    (taxInclusive ? discounted : discounted.add(tax).add(levy)).add(surcharge), discountPct, discountAmount, taxPct, levyPct,
                    surcharge, taxInclusive, taxExempt,
                    earlyPaymentPct, earlyPaymentDays, seedStatus(i.get("status")), issued, due);
            for (Map<String, Object> l : lineItems) {
                if (l.get("id") != null) {
                    jdbc.update("INSERT INTO invoice_line_item (id, invoice_id, description, qty, unit, unit_price, tax_exempt, discount_pct)"
                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                            ((Number) l.get("id")).longValue(), invoiceId, l.get("description"),
                            new BigDecimal(l.get("qty").toString()), l.get("unit"), new BigDecimal(l.get("unitPrice").toString()),
                            Boolean.TRUE.equals(l.get("taxExempt")), lineDiscountPct(l));
                } else {
                    jdbc.update("INSERT INTO invoice_line_item (invoice_id, description, qty, unit, unit_price, tax_exempt, discount_pct)"
                            + " VALUES (?, ?, ?, ?, ?, ?, ?)",
                            invoiceId, l.get("description"),
                            new BigDecimal(l.get("qty").toString()), l.get("unit"), new BigDecimal(l.get("unitPrice").toString()),
                            Boolean.TRUE.equals(l.get("taxExempt")), lineDiscountPct(l));
                }
            }
        }
        for (Map<String, Object> p : rows(fixture, "payments")) {
            jdbc.update("INSERT INTO payment (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
                    ((Number) p.get("id")).longValue(), ((Number) p.get("invoiceId")).longValue(),
                    new BigDecimal(p.get("amount").toString()), LocalDate.parse(p.get("date").toString()));
        }
        // Continue generated ids after the explicitly seeded ones.
        restartIdentity("client");
        restartIdentity("contact");
        restartIdentity("project");
        restartIdentity("invoice");
        restartIdentity("invoice_line_item");
        restartIdentity("task");
        restartIdentity("tag");
        restartIdentity("note");
        restartIdentity("payment");
    }

    /** A fixture timestamp, either a full instant or a bare date taken as the start of that day (UTC). */
    private static Instant seedInstant(String value) {
        return value.contains("T") ? Instant.parse(value) : LocalDate.parse(value).atStartOfDay(ZoneOffset.UTC).toInstant();
    }

    /**
     * Invoices without a status are seeded as new drafts. Older fixtures may describe an
     * issued-but-unpaid invoice as "UNPAID"; this domain models that state as SENT.
     */
    private static String seedStatus(Object status) {
        if (status == null) {
            return InvoiceStatus.DRAFT.name();
        }
        if ("UNPAID".equals(status)) {
            return InvoiceStatus.SENT.name();
        }
        return status.toString();
    }

    private void restartIdentity(String table) {
        Long next = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
    }

    @SuppressWarnings("unchecked")
    /** The percentage a fixture line item takes off itself; none when it does not say. */
    private static BigDecimal lineDiscountPct(Map<String, Object> lineItem) {
        return lineItem.get("discountPct") == null ? BigDecimal.ZERO
                : new BigDecimal(lineItem.get("discountPct").toString());
    }

    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
        Object value = fixture.get(key);
        return value == null ? List.of() : (List<Map<String, Object>>) value;
    }
}

package net.officefloor.hq.app.invoice;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.function.UnaryOperator;
import net.officefloor.hq.app.project.Project;

/**
 * An invoice raised against a project. It is built from line items, and can take either a percentage or
 * a flat amount off their sum as a discount, before tax (the flat amount shared across the lines in
 * proportion to what each charges, and never more than the subtotal), then add a percentage sales tax on what is left of the taxable lines only
 * (tax-free lines are never taxed), and optionally a second tax (a levy) worked out on the same taxable base;
 * its stored amount is always that subtotal less the discount plus the tax plus the levy, plus any flat
 * surcharge (such as a handling fee), which is added on last and is never taxed.
 * <p>
 * Every figure is worked out line by line: each line is rounded to the cent first and the rounded lines
 * are then added up, and the tax and levy are likewise worked out and rounded on each taxable line before
 * being added up, so the totals are sums of rounded lines rather than a rounded sum.
 * <p>
 * A tax-inclusive invoice (for a client whose prices already include tax) instead works the tax and
 * levy back out of the taxable lines after the discount: they are inside the price, so its amount is
 * just the subtotal less the discount (plus any surcharge), and the taxable base is what is left once they are taken out.
 * <p>
 * A tax-exempt invoice (for a tax-exempt client) has no taxable lines at all: it carries no tax or levy
 * whatever its lines or rates say, so its amount is the subtotal less the discount (plus any surcharge).
 */
@Entity
@Table(name = "invoice")
public class Invoice {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "project_id", nullable = false)
    private Project project;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount = BigDecimal.ZERO.setScale(2);

    @Column(name = "discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal discountPct = BigDecimal.ZERO.setScale(2);

    /** A flat amount taken off the subtotal (after the percentage); zero when there is none. */
    @Column(name = "discount_amount", nullable = false, precision = 12, scale = 2)
    private BigDecimal discountAmount = BigDecimal.ZERO.setScale(2);

    @Column(name = "tax_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal taxPct = BigDecimal.ZERO.setScale(2);

    @Column(name = "levy_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal levyPct = BigDecimal.ZERO.setScale(2);

    /** A flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal surcharge = BigDecimal.ZERO.setScale(2);

    /** Whether the prices already include the tax and levy, so they are backed out rather than added on. */
    @Column(name = "tax_inclusive", nullable = false)
    private boolean taxInclusive;

    /** Whether the invoice is for a tax-exempt client, so it carries no tax or levy whatever its lines say. */
    @Column(name = "tax_exempt", nullable = false)
    private boolean taxExempt;

    /** The percentage taken off what is owed when paid early; zero when no early-payment discount is offered. */
    @Column(name = "early_payment_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal earlyPaymentPct = BigDecimal.ZERO.setScale(2);

    /** How many days after being issued the invoice must be paid within to get the early-payment discount. */
    @Column(name = "early_payment_days", nullable = false)
    private int earlyPaymentDays;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 16)
    private InvoiceStatus status = InvoiceStatus.DRAFT;

    @Column(name = "issued_date", nullable = false)
    private LocalDate issuedDate;

    @Column(name = "due_date", nullable = false)
    private LocalDate dueDate;

    @OneToMany(mappedBy = "invoice", cascade = CascadeType.ALL, orphanRemoval = true)
    @OrderBy("id")
    private List<InvoiceLineItem> lineItems = new ArrayList<>();

    protected Invoice() {
    }

    public Invoice(Project project, LocalDate issuedDate, LocalDate dueDate) {
        this.project = project;
        this.issuedDate = issuedDate;
        this.dueDate = dueDate;
        this.taxInclusive = project.getClient().isTaxInclusive();
        this.taxExempt = project.getClient().isTaxExempt();
    }

    public Long getId() {
        return id;
    }

    public Project getProject() {
        return project;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    /**
     * The total before tax: the amount owed less the sales tax and levy, whether they were added on or
     * are included in the prices.
     */
    public BigDecimal getTotalExTax() {
        return amount.subtract(getTax()).subtract(getLevy());
    }

    /**
     * The overall tax rate that actually ended up on the invoice: the sales tax and levy together as a
     * percentage of the total before tax, to two decimal places. It is below the headline rates when some
     * lines are tax-free, and zero when there is nothing before tax to charge it on.
     */
    public BigDecimal getEffectiveTaxPct() {
        BigDecimal totalExTax = getTotalExTax();
        if (totalExTax.signum() == 0) {
            return BigDecimal.ZERO.setScale(2);
        }
        return getTax().add(getLevy()).multiply(BigDecimal.valueOf(100)).divide(totalExTax, 2, RoundingMode.HALF_UP);
    }

    /** The percentage taken off the subtotal; zero when there is no discount. */
    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    /** The flat amount asked to be taken off the subtotal; zero when there is no flat discount. */
    public BigDecimal getDiscountAmount() {
        return discountAmount;
    }

    /**
     * What the line items add up to, before the invoice's discount: the sum of each line after its own
     * discount, rounded to the cent.
     */
    public BigDecimal getSubtotal() {
        return lineItems.stream().map(InvoiceLineItem::getAmount).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** How much the discount (the percentage and the flat amount together) takes off the subtotal, to the cent. */
    public BigDecimal getDiscount() {
        BigDecimal subtotal = getSubtotal();
        return percentOf(subtotal, discountPct).add(flatDiscountOn(subtotal));
    }

    /** The sales tax percentage added after the discount; zero when there is no tax. */
    public BigDecimal getTaxPct() {
        return taxPct;
    }

    /** Whether the prices already include the tax and levy, so they are worked back out rather than added on. */
    public boolean isTaxInclusive() {
        return taxInclusive;
    }

    /** Whether the invoice is for a tax-exempt client, so none of its lines are taxed. */
    public boolean isTaxExempt() {
        return taxExempt;
    }

    /**
     * What the sales tax is charged on: the taxable lines (leaving out tax-free ones) less the discount
     * taken off them, to the cent. On a tax-inclusive invoice that is what is left of them once the tax
     * and levy inside them are taken out.
     */
    public BigDecimal getTaxableBase() {
        BigDecimal gross = getDiscountedTaxable();
        return taxInclusive ? gross.subtract(getTax()).subtract(getLevy()) : gross;
    }

    /**
     * How much sales tax is added on the taxable base (or is inside it, when tax-inclusive): the tax on
     * each taxable line rounded to the cent, added up.
     */
    public BigDecimal getTax() {
        return sumOverTaxableLines(this::taxOn);
    }

    /** The levy (second tax) percentage added on top of the sales tax; zero when there is no levy. */
    public BigDecimal getLevyPct() {
        return levyPct;
    }

    /**
     * How much levy is added on the taxable base (or is inside it, when tax-inclusive): the levy on each
     * taxable line rounded to the cent, added up.
     */
    public BigDecimal getLevy() {
        return sumOverTaxableLines(this::levyOn);
    }

    /** The flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
    public BigDecimal getSurcharge() {
        return surcharge;
    }

    /** The taxable lines (leaving out tax-free ones), each less the discount taken off it, added up. */
    private BigDecimal getDiscountedTaxable() {
        return sumOverTaxableLines(line -> line);
    }

    /**
     * Works a figure out on each taxable line after its discount, to the cent, and adds them up. A
     * tax-exempt invoice has no taxable lines.
     */
    private BigDecimal sumOverTaxableLines(UnaryOperator<BigDecimal> perLine) {
        return lineItems.stream().filter(l -> !taxExempt && !l.isTaxExempt()).map(InvoiceLineItem::getAmount)
                .map(amount -> perLine.apply(amount.subtract(discountOn(amount))))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /**
     * The part of a tax-inclusive price that is the given percentage, worked back out of it: the price
     * divided in proportion to the sales tax and levy rates it includes (e.g. 20% tax in 120 is 20).
     */
    private BigDecimal includedIn(BigDecimal price, BigDecimal pct) {
        BigDecimal grossPct = BigDecimal.valueOf(100).add(taxPct).add(levyPct);
        return price.multiply(pct).divide(grossPct, 2, RoundingMode.HALF_UP);
    }

    /** The percentage taken off what is owed when paid early; zero when none is offered. */
    public BigDecimal getEarlyPaymentPct() {
        return earlyPaymentPct;
    }

    /** How many days after being issued the invoice must be paid within to get the early-payment discount. */
    public int getEarlyPaymentDays() {
        return earlyPaymentDays;
    }

    /** Whether an early-payment discount is offered: a percentage off when paid within some days. */
    public boolean offersEarlyPayment() {
        return earlyPaymentPct.signum() > 0 && earlyPaymentDays > 0;
    }

    /** The last day the invoice can be paid to get the early-payment discount; null when none is offered. */
    public LocalDate getEarlyPaymentBy() {
        return offersEarlyPayment() ? issuedDate.plusDays(earlyPaymentDays) : null;
    }

    /**
     * The reduced amount to pay when settling early: the amount less the early-payment percentage of it,
     * to the cent; null when no early-payment discount is offered.
     */
    public BigDecimal getEarlyPaymentAmount() {
        return offersEarlyPayment() ? amount.subtract(percentOf(amount, earlyPaymentPct)) : null;
    }

    public InvoiceStatus getStatus() {
        return status;
    }

    public LocalDate getIssuedDate() {
        return issuedDate;
    }

    public LocalDate getDueDate() {
        return dueDate;
    }

    public List<InvoiceLineItem> getLineItems() {
        return List.copyOf(lineItems);
    }

    /** Adds a line to this invoice and reworks its amount to include what the line charges. */
    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice) {
        return addLineItem(description, qty, unit, unitPrice, false, BigDecimal.ZERO);
    }

    /**
     * Adds a line, taxable or tax-free and with any discount of its own, to this invoice and reworks its
     * amount to include what the line charges after that discount.
     */
    public InvoiceLineItem addLineItem(String description, BigDecimal qty, String unit, BigDecimal unitPrice,
            boolean taxExempt, BigDecimal discountPct) {
        InvoiceLineItem item = new InvoiceLineItem(this, description, qty, unit, unitPrice, taxExempt, discountPct);
        lineItems.add(item);
        recalculateAmount();
        return item;
    }

    /** Changes one of this invoice's lines and reworks its amount to match. */
    public void updateLineItem(InvoiceLineItem item, String description, BigDecimal qty, String unit,
            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct) {
        item.update(description, qty, unit, unitPrice, taxExempt, discountPct);
        recalculateAmount();
    }

    /** Removes a line from this invoice and reworks its amount to no longer include what the line charged. */
    public void removeLineItem(InvoiceLineItem item) {
        lineItems.remove(item);
        recalculateAmount();
    }

    /** The line on this invoice with the given id, if there is one. */
    public Optional<InvoiceLineItem> findLineItem(Long lineItemId) {
        return lineItems.stream().filter(l -> l.getId().equals(lineItemId)).findFirst();
    }

    /** Sets the percentage taken off this invoice and reworks its amount to match. */
    public void applyDiscount(BigDecimal discountPct) {
        applyDiscount(discountPct, BigDecimal.ZERO);
    }

    /**
     * Sets the discount on this invoice, either a percentage or a flat amount (the other being zero), and
     * reworks its amount to match.
     */
    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount) {
        if (discountPct.signum() != 0 && discountAmount.signum() != 0) {
            throw new IllegalArgumentException("A discount is either a percentage or a flat amount, not both");
        }
        this.discountPct = discountPct.setScale(2, RoundingMode.HALF_UP);
        this.discountAmount = discountAmount.setScale(2, RoundingMode.HALF_UP);
        recalculateAmount();
    }

    /** Sets the sales tax percentage added to this invoice and reworks its amount to match. */
    public void applyTax(BigDecimal taxPct) {
        this.taxPct = taxPct.setScale(2, RoundingMode.HALF_UP);
        recalculateAmount();
    }

    /** Sets whether this invoice's prices already include tax and reworks its amount to match. */
    public void applyTaxInclusive(boolean taxInclusive) {
        this.taxInclusive = taxInclusive;
        recalculateAmount();
    }

    /** Sets whether this invoice is for a tax-exempt client and reworks its amount to match. */
    public void applyTaxExempt(boolean taxExempt) {
        this.taxExempt = taxExempt;
        recalculateAmount();
    }

    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
    public void applyLevy(BigDecimal levyPct) {
        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
        recalculateAmount();
    }

    /** Sets the flat surcharge (such as a handling fee) added to this invoice and reworks its amount to match. */
    public void applySurcharge(BigDecimal surcharge) {
        this.surcharge = surcharge.setScale(2, RoundingMode.HALF_UP);
        recalculateAmount();
    }

    /**
     * Sets the early-payment discount offered on this invoice: the percentage taken off if it is paid
     * within the given number of days of being issued. It does not change the amount owed.
     */
    public void applyEarlyPayment(BigDecimal earlyPaymentPct, int earlyPaymentDays) {
        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
        this.earlyPaymentDays = earlyPaymentDays;
    }

    /**
     * The discount taken off one line, to the cent: its percentage, plus its share of the flat amount in
     * proportion to what the line charges out of the subtotal.
     */
    private BigDecimal discountOn(BigDecimal line) {
        BigDecimal pct = percentOf(line, discountPct);
        BigDecimal subtotal = getSubtotal();
        if (subtotal.signum() == 0) {
            return pct;
        }
        BigDecimal flatShare = flatDiscountOn(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
        return pct.add(flatShare);
    }

    /** The flat amount actually taken off the subtotal: never more than is left after the percentage. */
    private BigDecimal flatDiscountOn(BigDecimal subtotal) {
        BigDecimal left = subtotal.subtract(percentOf(subtotal, discountPct)).max(BigDecimal.ZERO.setScale(2));
        return discountAmount.min(left);
    }

    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
    private BigDecimal taxOn(BigDecimal line) {
        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
    }

    /** The levy on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
    private BigDecimal levyOn(BigDecimal line) {
        return taxInclusive ? includedIn(line, levyPct) : percentOf(line, levyPct);
    }

    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
    }

    private void recalculateAmount() {
        BigDecimal subtotal = getSubtotal();
        BigDecimal discounted = subtotal.subtract(getDiscount());
        this.amount = (taxInclusive ? discounted : discounted.add(getTax()).add(getLevy())).add(surcharge);
    }

    /** Marks this invoice as sent to the client. */
    public void markSent() {
        this.status = InvoiceStatus.SENT;
    }

    /** Cancels this invoice, so it is no longer owed. */
    public void markVoid() {
        this.status = InvoiceStatus.VOID;
    }

    /** What is left to pay on this invoice given the total paid against it; nothing once it is void. */
    public BigDecimal amountDue(BigDecimal paid) {
        return status == InvoiceStatus.VOID ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid);
    }

    /**
     * Works out this sent invoice's status from the total paid against it: PAID once the payments
     * cover the amount, PARTIAL once something has been paid, otherwise still SENT.
     */
    public void applyPaidTotal(BigDecimal paid) {
        if (status == InvoiceStatus.DRAFT || status == InvoiceStatus.VOID) {
            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be paid");
        }
        if (paid.compareTo(amount) >= 0) {
            this.status = InvoiceStatus.PAID;
        } else if (paid.signum() > 0) {
            this.status = InvoiceStatus.PARTIAL;
        } else {
            this.status = InvoiceStatus.SENT;
        }
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.payment.PaymentRepository;
import net.officefloor.hq.app.project.Project;
import net.officefloor.hq.app.project.ProjectRepository;
import net.officefloor.hq.app.settings.SettingsService;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final ProjectRepository projects;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final SettingsService settings;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, ProjectRepository projects, PaymentRepository payments,
            ClientRepository clients, SettingsService settings, Audit audit) {
        this.invoices = invoices;
        this.projects = projects;
        this.clients = clients;
        this.payments = payments;
        this.settings = settings;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<InvoiceResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
        }
        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        return found.stream()
                .map(i -> InvoiceResponse.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
    }

    /**
     * A client's statement: every invoice across their projects with what is left to pay on each, and
     * the total they still owe, also grouped by job with a subtotal per job. Drafts are listed but not owed, as they have not been sent, nor are
     * void invoices, as they have been cancelled.
     */
    @Transactional(readOnly = true)
    public ClientStatementResponse statementForClient(Long clientId) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        List<ClientStatementResponse.Line> lines = found.stream()
                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines);
    }

    private Map<Long, BigDecimal> paidByInvoice(List<Invoice> found) {
        return found.isEmpty() ? Map.of()
                : payments.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
                        .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
                                PaymentRepository.InvoicePaidTotal::getPaid));
    }

    /**
     * One page of the invoices across all projects, with the name of the project each one is for,
     * narrowed to the given status when one is supplied. Pages are numbered from zero.
     */
    @Transactional(readOnly = true)
    public InvoicePageResponse listAll(InvoiceStatus status, int page, int size) {
        PageRequest request = PageRequest.of(page, size);
        Page<Invoice> found = status == null ? invoices.findPageWithProject(request)
                : invoices.findPageWithProjectByStatus(status, request);
        return InvoicePageResponse.from(found);
    }

    @Transactional
    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
        Project project = projects.findById(projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
        if (due.isBefore(issued)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
        }
        Invoice invoice = new Invoice(project, issued, due);
        if (request.amount() != null) {
            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, null, request.amount());
        }
        invoice.applyTax(request.taxPct() != null ? request.taxPct() : settings.defaultTaxPct());
        Invoice saved = invoices.save(invoice);
        return InvoiceResponse.from(saved, BigDecimal.ZERO);
    }

    /** A single invoice with its line items. */
    @Transactional(readOnly = true)
    public InvoiceDetailResponse get(Long projectId, Long invoiceId) {
        return InvoiceDetailResponse.from(find(projectId, invoiceId));
    }

    /** Adds a line item to a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse addLineItem(Long projectId, Long invoiceId, LineItemRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.addLineItem(request.description().strip(), request.qty(), request.normalizedUnit(), request.unitPrice(),
                request.exempt(), request.lineDiscountPct());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Changes a line item on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse updateLineItem(Long projectId, Long invoiceId, Long lineItemId,
            LineItemRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        InvoiceLineItem item = findLineItem(invoice, lineItemId);
        invoice.updateLineItem(item, request.description().strip(), request.qty(), request.normalizedUnit(),
                request.unitPrice(), request.exempt(), request.lineDiscountPct());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Removes a line item from a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse removeLineItem(Long projectId, Long invoiceId, Long lineItemId) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.removeLineItem(findLineItem(invoice, lineItemId));
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the percentage or flat discount on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse applyDiscount(Long projectId, Long invoiceId, DiscountRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applyDiscount(request.discountPct(), request.flatAmount());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the sales tax percentage on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse applyTax(Long projectId, Long invoiceId, TaxRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applyTax(request.taxPct());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the levy (second tax) percentage on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse applyLevy(Long projectId, Long invoiceId, LevyRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applyLevy(request.levyPct());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the flat surcharge on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse applySurcharge(Long projectId, Long invoiceId, SurchargeRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applySurcharge(request.surcharge());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sets the early-payment discount offered on a draft invoice. */
    @Transactional
    public InvoiceDetailResponse applyEarlyPayment(Long projectId, Long invoiceId, EarlyPaymentRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.applyEarlyPayment(request.earlyPaymentPct(), request.earlyPaymentDays());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sends a draft invoice and records the sending in the audit log. */
    @Transactional
    public InvoiceResponse send(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
        }
        if (invoice.getAmount().signum() == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
        }
        invoice.markSent();
        invoices.flush();
        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return toResponse(invoice);
    }

    /**
     * Cancels an invoice sent by mistake, so it no longer counts toward what is owed, and records the
     * cancellation in the audit log. Only a sent invoice with nothing yet paid against it can be voided.
     */
    @Transactional
    public InvoiceResponse cancel(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.SENT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "Only a sent invoice with no payments recorded can be cancelled");
        }
        invoice.markVoid();
        invoices.flush();
        audit.record("INVOICE_VOIDED id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return toResponse(invoice);
    }

    private InvoiceResponse toResponse(Invoice invoice) {
        return InvoiceResponse.from(invoice, payments.sumAmountByInvoiceId(invoice.getId()));
    }

