362	        recalculateAmount();
363	    }
364	
365	    /** Sets the levy (second tax) percentage added to this invoice and reworks its amount to match. */
366	    public void applyLevy(BigDecimal levyPct) {
367	        this.levyPct = levyPct.setScale(2, RoundingMode.HALF_UP);
368	        recalculateAmount();
369	    }
370	
371	    /** Sets the flat surcharge (such as a handling fee) added to this invoice and reworks its amount to match. */
372	    public void applySurcharge(BigDecimal surcharge) {
