374	        recalculateAmount();
375	    }
376	
377	    /**
378	     * Sets the early-payment discount offered on this invoice: the percentage taken off if it is paid
379	     * within the given number of days of being issued. It does not change the amount owed.
380	     */
381	    public void applyEarlyPayment(BigDecimal earlyPaymentPct, int earlyPaymentDays) {
382	        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
383	        this.earlyPaymentDays = earlyPaymentDays;
384	    }
385	
386	    /**
387	     * The discount taken off one line, to the cent: its percentage, plus its share of the flat amount in
388	     * proportion to what the line charges out of the subtotal.
389	     */
390	    private BigDecimal discountOn(BigDecimal line) {
391	        BigDecimal pct = percentOf(line, discountPct);
392	        BigDecimal subtotal = getSubtotal();
393	        if (subtotal.signum() == 0) {
394	            return pct;
395	        }
396	        BigDecimal flatShare = flatDiscountOn(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
397	        return pct.add(flatShare);
398	    }
399	
400	    /** The flat amount actually taken off the subtotal: never more than is left after the percentage. */
401	    private BigDecimal flatDiscountOn(BigDecimal subtotal) {
402	        BigDecimal left = subtotal.subtract(percentOf(subtotal, discountPct)).max(BigDecimal.ZERO.setScale(2));
403	        return discountAmount.min(left);
404	    }
