421	        BigDecimal subtotal = getSubtotal();
422	        BigDecimal discounted = subtotal.subtract(getDiscount());
423	        this.amount = (taxInclusive ? discounted : discounted.add(getTax()).add(getLevy())).add(surcharge);
424	    }
425	
