432	    public void markVoid() {
433	        this.status = InvoiceStatus.VOID;
434	    }
435	
436	    /** What is left to pay on this invoice given the total paid against it; nothing once it is void. */
437	    public BigDecimal amountDue(BigDecimal paid) {
438	        return status == InvoiceStatus.VOID ? BigDecimal.ZERO.setScale(2) : amount.subtract(paid);
439	    }
440	
441	    /**
442	     * Works out this sent invoice's status from the total paid against it: PAID once the payments
443	     * cover the amount, PARTIAL once something has been paid, otherwise still SENT.
444	     */
445	    public void applyPaidTotal(BigDecimal paid) {
446	        if (status == InvoiceStatus.DRAFT || status == InvoiceStatus.VOID) {
447	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be paid");
448	        }
449	        if (paid.compareTo(amount) >= 0) {
450	            this.status = InvoiceStatus.PAID;
451	        } else if (paid.signum() > 0) {
452	            this.status = InvoiceStatus.PARTIAL;
453	        } else {
454	            this.status = InvoiceStatus.SENT;
455	        }
